INSERT INTO `lab_test_templates` VALUES (1,11,'Bs for mps','BS','To detect malaria parasite in blood','blood',NULL,NULL,NULL,24,100.00,1,'2026-03-06 18:19:54','2026-03-06 22:57:03','2026-03-06 22:57:03'),(2,11,'Bs for mps','BS1','To detect malaria parasite in blood','blood',NULL,NULL,NULL,24,100.00,1,'2026-03-06 22:56:26','2026-03-07 07:11:11','2026-03-07 07:11:11'),(3,2,'Liver Function Tests','LFTs','Assess liver health anf Functions','blood','5ml','SST tube (gold top)',NULL,6,3500.00,1,'2026-03-04 07:29:56','2026-03-05 08:38:11',NULL),(4,2,'Kidney Function Tests','KFT','Assess kidney health','blood','5ml','SST tube (gold top)',NULL,6,900.00,1,'2026-03-04 07:29:56','2026-03-04 07:29:56',NULL),(5,6,'Urinalysis','U/A','Detects abnoomarlities in the urine that may indicate kidney diseases, diabetes or urinary tract infections','urine','50ml','Sterile urine container','Mid-stream clean catch sample',3,200.00,1,'2026-03-04 07:29:56','2026-03-07 07:43:41',NULL),(6,2,'Blood Glucose Levels','RBS/FBS','Measures blood glucose levels to diagnose and monitor diabetes.','blood','2ml','Gray top (fluoride)','Fasting for 8-12 hours required',1,200.00,1,'2026-03-04 07:29:56','2026-03-05 07:57:04',NULL),(8,4,'Pregnancy Detection Test','PDT','Detects human chorionic gonadotropin hormone to confirm pregnancy.','urine',NULL,'Sterile Urine Bottle',NULL,2,100.00,1,'2026-03-05 07:54:55','2026-03-05 07:54:55',NULL),(9,4,'Brucellin Antigen Test','BAT','Detects antibodies against Brucella species to diagnose brucellosis.','blood',NULL,NULL,NULL,2,200.00,1,'2026-03-05 08:00:32','2026-03-05 08:00:32',NULL),(10,3,'Salmonella Antigen Test','SAT','Detects antibodies against Salmonella organisms, commonly used in typhoid diagnosis.','stool',NULL,NULL,NULL,24,500.00,1,'2026-03-05 08:01:45','2026-03-05 08:01:45',NULL),(11,3,'H. Pylori Test','H-pylori','Detects Helicobacter pylori infection linked to gastritis and peptic ulcers','stool',NULL,NULL,NULL,2,500.00,1,'2026-03-05 08:03:09','2026-03-05 08:03:09',NULL),(12,11,'Stool Analysis','O/C','Identifies intestinal parasites, ova, cysts, bacteria, and digestive','stool',NULL,NULL,NULL,2,200.00,1,'2026-03-05 08:13:49','2026-03-05 08:13:49',NULL),(13,4,'Rheumatoid Factor','RF','Detects rheumatoid factor antibodies associated with rheumatoid arthritis.','blood',NULL,NULL,NULL,2,200.00,1,'2026-03-05 08:26:27','2026-03-05 08:26:27',NULL),(14,4,'ASOT','ASOT','Detects antibodies against Streptococcus bacteria, linked to rheumatic fever and post-strep complications.','blood',NULL,NULL,NULL,2,200.00,1,'2026-03-05 08:27:24','2026-03-05 08:27:24',NULL),(15,4,'VDRL','VDRL','Screens for syphilis infection.','blood',NULL,NULL,NULL,24,200.00,1,'2026-03-05 08:31:50','2026-03-05 08:31:50',NULL),(16,1,'Blood Grouping','Blood Group','Determines ABO and Rh blood type for transfusion compatibility.','blood',NULL,NULL,NULL,24,200.00,1,'2026-03-05 08:33:22','2026-03-05 08:33:22',NULL),(17,1,'Hemoglobin Level','HB','Measures haemoglobin concentration to assess anemia or polycythemia.','blood',NULL,NULL,NULL,2,200.00,1,'2026-03-05 08:34:55','2026-03-05 08:34:55',NULL),(18,2,'Electrolyte Panel','UECs','Assesses kidney function and electrolyte balance.','blood',NULL,NULL,NULL,2,2000.00,1,'2026-03-05 08:39:44','2026-03-05 08:39:44',NULL),(19,2,'Thryroid Function Tests','TFTs','Evaluates thyroid gland function.','blood',NULL,NULL,NULL,3,3000.00,1,'2026-03-05 08:44:37','2026-03-05 08:44:37',NULL),(20,2,'Prostrate Antigen Test','PSA','Screens for prostate enlargement, inflammation, or cancer.','blood',NULL,NULL,NULL,24,2500.00,1,'2026-03-05 08:46:05','2026-03-05 08:46:05',NULL),(21,1,'HbA1c','HbA1c','Measures average blood glucose control over the past 2–3 months','blood',NULL,NULL,NULL,2,1500.00,1,'2026-03-05 08:48:31','2026-03-05 08:48:31',NULL),(22,11,'Bs For Mps','Bs.','Detects malaria parasites in blood and confirms malaria infection.','blood',NULL,NULL,NULL,2,100.00,1,'2026-03-07 07:16:08','2026-03-07 07:16:08',NULL),(23,1,'Complete Blood Count','CBC','Assesses Overal Health, Identifies conditions Like anemia, Infections and many other disorders','blood',NULL,NULL,NULL,3,800.00,1,'2026-03-07 07:19:09','2026-03-07 07:19:09',NULL),(24,4,'Provider Initiated Testing and Counselling for HIV','PITC','Screens for HIV infection and provides counselling.','blood',NULL,NULL,NULL,24,200.00,1,'2026-03-11 12:49:25','2026-03-12 07:32:36',NULL),(25,11,'Malaria Rapid Diagnostic Test','MRDT','Detects malaria antigens in blood to diagnose malaria infection quickly without microscopy.','blood',NULL,NULL,NULL,24,100.00,1,'2026-03-12 07:35:31','2026-03-12 07:35:31',NULL),(26,4,'Widal Test','Widal','Detects antibodies against Salmonella Typhi and Paratyphi organisms to help diagnose typhoid fever.','blood',NULL,NULL,NULL,24,200.00,1,'2026-03-12 07:41:27','2026-03-12 07:41:27',NULL),(27,1,'Sickle Cell Screening Test','Sickling Test','Detects the presence of hemoglobin S (HbS) in red blood cells to identify sickle cell disease or sickle cell trait.\n\nResult interpretation\n\nNegative: No sickle hemoglobin detected.\n\nPositive: Presence of HbS, suggests sickle cell trait or sickle cell disease.','blood',NULL,NULL,NULL,24,200.00,1,'2026-03-12 07:45:42','2026-03-12 07:47:50',NULL),(28,1,'Peripheral Blood Film','PBF','PBF Is a Microscopic Examination Of Blood Used to Detect Abnomarlities in Blood Cells and Parasites','blood',NULL,NULL,NULL,24,200.00,1,'2026-05-28 10:25:12','2026-05-28 10:25:12',NULL);
